import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { logistikAPI, requestAPI } from '../../services/api';
import { getUser } from '../../utils/auth';

const LogistikDashboard = () => {
  const [stats, setStats] = useState({
    totalRoomRequests: 0,
    pendingRooms: 0,
    approvedRooms: 0,
    rejectedRooms: 0,
    totalRooms: 0
  });
  const [recentRequests, setRecentRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [rejectionReason, setRejectionReason] = useState('');
  const user = getUser();

  useEffect(() => {
    console.log('🔍 Current user in LogistikDashboard:', user);
    if (!user) {
      console.log('❌ No user found, redirecting to login');
      window.location.href = '/login';
      return;
    }
    
    if (user.role !== 'logistik') {
      console.log(`❌ User role "${user.role}" is not logistik`);
      toast.error(`Akses ditolak. Dashboard ini hanya untuk role logistik. Role Anda: ${user.role}`);
      return;
    }
    
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching logistik dashboard data...');
      
      // Gunakan API yang tersedia
      const dashboardRes = await logistikAPI.getDashboard();
      const requestsRes = await requestAPI.getAll();
      
      console.log('✅ Dashboard data received:', dashboardRes);
      
      const requests = requestsRes.data;
      // Filter untuk room requests saja
      const roomRequests = requests.filter(r => 
        r.request_type === 'room' || r.request_type === 'both'
      );
      
      setStats({
        totalRoomRequests: roomRequests.length || 0,
        pendingRooms: roomRequests.filter(r => r.status === 'pending').length || 0,
        approvedRooms: roomRequests.filter(r => r.status === 'approved').length || 0,
        rejectedRooms: roomRequests.filter(r => r.status === 'rejected').length || 0
      });
      
      setRecentRequests(roomRequests.slice(0, 10) || []);
      
    } catch (error) {
      console.error('❌ Error fetching dashboard data:', error);
      console.error('Error details:', error.response?.data);
      
      // Fallback ke endpoint lama jika endpoint baru belum ready
      try {
        console.log('🔄 Trying fallback to legacy endpoints...');
        const [requestsRes, roomsRes] = await Promise.all([
          logistikAPI.getRoomRequestsLegacy(), // Ini akan hit /api/requests/room-requests
          logistikAPI.getRooms()        // Ini akan hit /api/requests/rooms  
        ]);

        console.log('✅ Requests response:', requestsRes);
        console.log('✅ Rooms response:', roomsRes);

        const requests = requestsRes.data;
        const rooms = roomsRes.data;

        // Filter requests yang memerlukan room approval
        const roomRequests = requests.filter(r => 
          r.request_type === 'room' || r.request_type === 'both'
        );

        // Calculate stats
        const stats = {
          totalRoomRequests: roomRequests.length,
          pendingRooms: roomRequests.filter(r => r.room_status === 'pending').length,
          approvedRooms: roomRequests.filter(r => r.room_status === 'approved').length,
          rejectedRooms: roomRequests.filter(r => r.room_status === 'rejected').length,
          totalRooms: rooms.length
        };

        setStats(stats);
        setRecentRequests(roomRequests.slice(0, 5));
        
      } catch (fallbackError) {
        console.error('❌ Fallback also failed:', fallbackError);
        console.error('Error details:', {
          status: fallbackError.response?.status,
          statusText: fallbackError.response?.statusText,
          data: fallbackError.response?.data,
          message: fallbackError.message
        });
        
        if (fallbackError.response?.status === 403) {
          toast.error(`Akses ditolak: ${fallbackError.response?.data?.message || 'Role tidak sesuai'}`);
        } else if (fallbackError.response?.status === 401) {
          toast.error('Sesi habis, silakan login kembali');
          window.location.href = '/login';
        } else {
          toast.error('Gagal memuat data dashboard: ' + (fallbackError.response?.data?.message || fallbackError.message));
        }
      }
    } finally {
      setLoading(false);
    }
  };

  const handleApproveRoom = (request) => {
    setSelectedRequest(request);
    setShowApproveModal(true);
  };

  const handleRejectRoom = (request) => {
    setSelectedRequest(request);
    setShowRejectModal(true);
  };

  const submitApprove = async () => {
    try {
      console.log('🔄 Approving room request:', selectedRequest.id);
      
      // Gunakan BPMN API baru untuk approval
      await requestAPI.updateStatus(selectedRequest.id, {
        status: 'approved',
        reason: 'Ruangan disetujui oleh logistik'
      });
      
      toast.success('Request ruangan berhasil disetujui!');
      fetchDashboardData();
      setShowApproveModal(false);
    } catch (error) {
      console.error('Error approving room request:', error);
      toast.error('Gagal menyetujui request ruangan: ' + (error.response?.data?.message || error.message));
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      console.log('🔄 Rejecting room request:', selectedRequest.id);
      
      // Gunakan API yang tersedia
      await requestAPI.updateStatus(selectedRequest.id, {
        status: 'rejected',
        reason: rejectionReason
      });
      
      toast.success('Request ruangan berhasil ditolak!');
      fetchDashboardData();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting room request:', error);
      toast.error('Gagal menolak request ruangan: ' + (error.response?.data?.message || error.message));
    }
  };

  const getStatusBadge = (request) => {
    // Untuk logistik, kita fokus pada room_status
    const status = request.room_status || request.status;
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger',
      not_required: 'secondary'
    };
    const labels = {
      pending: 'PENDING',
      approved: 'APPROVED', 
      rejected: 'REJECTED',
      not_required: 'NOT REQUIRED'
    };
    return <Badge bg={variants[status]}>{labels[status] || status.toUpperCase()}</Badge>;
  };

  const getTypeBadge = (type) => {
    const variants = {
      room: 'info',
      zoom: 'primary',
      both: 'success'
    };
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    return <Badge bg={variants[type]}>{labels[type]}</Badge>;
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Dashboard Logistik</h2>
          <p className="text-muted">Selamat datang, {user?.name || user?.email}!</p>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/logistik/rooms" variant="primary" className="me-2">
            <i className="fas fa-building me-2"></i>
            Kelola Ruangan
          </Button>
          <Button as={Link} to="/logistik/bookings" variant="outline-primary">
            <i className="fas fa-list me-2"></i>
            Semua Booking Ruangan
          </Button>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={2}>
          <Card className="text-center h-100 border-primary">
            <Card.Body>
              <i className="fas fa-door-open fa-2x text-primary mb-2"></i>
              <h3>{stats.totalRoomRequests}</h3>
              <p className="text-muted mb-0">Total Request</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-warning">
            <Card.Body>
              <i className="fas fa-clock fa-2x text-warning mb-2"></i>
              <h3>{stats.pendingRooms}</h3>
              <p className="text-muted mb-0">Pending</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-success">
            <Card.Body>
              <i className="fas fa-check-circle fa-2x text-success mb-2"></i>
              <h3>{stats.approvedRooms}</h3>
              <p className="text-muted mb-0">Approved</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-danger">
            <Card.Body>
              <i className="fas fa-times-circle fa-2x text-danger mb-2"></i>
              <h3>{stats.rejectedRooms}</h3>
              <p className="text-muted mb-0">Rejected</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-info">
            <Card.Body>
              <i className="fas fa-building fa-2x text-info mb-2"></i>
              <h3>{stats.totalRooms}</h3>
              <p className="text-muted mb-0">Total Ruangan</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Room Requests */}
      <Row>
        <Col>
          <Card>
            <Card.Header className="d-flex justify-content-between align-items-center">
              <h5 className="mb-0">Request Ruangan Terbaru</h5>
              <Button as={Link} to="/logistik/bookings" variant="outline-primary" size="sm">
                Lihat Semua
              </Button>
            </Card.Header>
            <Card.Body>
              {recentRequests.length > 0 ? (
                <Table responsive>
                  <thead>
                    <tr>
                      <th>User</th>
                      <th>Judul</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentRequests.map((request) => (
                      <tr key={request.id}>
                        <td>{request.user_email}</td>
                        <td>{request.title}</td>
                        <td>{new Date(request.date).toLocaleDateString('id-ID')}</td>
                        <td>{request.start_time} - {request.end_time}</td>
                        <td>{getTypeBadge(request.request_type)}</td>
                        <td>{request.capacity} orang</td>
                        <td>{getStatusBadge(request)}</td>
                        <td>
                          {request.room_status === 'pending' && (request.request_type === 'room' || request.request_type === 'both') && (
                            <div className="btn-group">
                              <Button
                                variant="success"
                                size="sm"
                                onClick={() => handleApproveRoom(request)}
                                title="Approve ruangan"
                              >
                                <i className="fas fa-check"></i>
                              </Button>
                              <Button
                                variant="danger"
                                size="sm"
                                onClick={() => handleRejectRoom(request)}
                                title="Reject ruangan"
                              >
                                <i className="fas fa-times"></i>
                              </Button>
                            </div>
                          )}
                          {request.room_status === 'approved' && (
                            <Badge bg="success">Sudah Disetujui</Badge>
                          )}
                          {request.room_status === 'rejected' && (
                            <Badge bg="danger">Sudah Ditolak</Badge>
                          )}
                          {request.room_status === 'not_required' && (
                            <Badge bg="secondary">Tidak Perlu Ruangan</Badge>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-4">
                  <i className="fas fa-inbox fa-3x text-muted mb-3"></i>
                  <p className="text-muted">Tidak ada request ruangan terbaru</p>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Setujui Request Ruangan</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <p>Anda akan menyetujui request ruangan:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
                <li><strong>Waktu:</strong> {selectedRequest.start_time} - {selectedRequest.end_time}</li>
                <li><strong>Kapasitas:</strong> {selectedRequest.capacity} orang</li>
              </ul>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button variant="success" onClick={submitApprove}>
            Setujui
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Tolak Request Ruangan</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <p>Anda akan menolak request ruangan:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
              </ul>

              <Form.Group className="mt-3">
                <Form.Label>Alasan Penolakan:</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Jelaskan alasan penolakan..."
                  required
                />
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button variant="danger" onClick={submitReject}>
            Tolak
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default LogistikDashboard;
